import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

class SomeTestClass {
    void example(List<String> strings) {
        strings.stream()



                .forEach(it -> System.out.println(it)); // should be reported here
    }
}

import java.util.Arrays;
import java.util.stream.Stream;
import java.util.stream.Collectors;

class SomeTestClass {
    void example(Stream<String> strings) {
        boolean b;
        b = strings.anyMatch(it -> it.isEmpty()); // ok
        b = !strings.anyMatch(it -> it.isEmpty()); // noneMatch(String::isEmpty)
        b = !strings.anyMatch(it -> !it.isEmpty()); // allMatch(String::isEmpty)
        b = !strings.allMatch(it -> !it.isEmpty()); // anyMatch(String::isEmpty)
        b = !strings.noneMatch(it -> !it.isEmpty()); // !allMatch(String::isEmpty)

        b = strings.anyMatch(it -> !it.isEmpty()); // ok
        b = strings.allMatch(it -> !it.isEmpty()); // noneMatch(String::isEmpty)
        b = strings.noneMatch(it -> !it.isEmpty()); // allMatch(String::isEmpty)

        b = !strings.allMatch(it -> it.isEmpty()); // ok
        b = !strings.noneMatch(it -> it.isEmpty()); // anyMatch(String::isEmpty)
    }
}
